// CSD_RATIONALE_BEGIN
// Failure analysis: All 144 mode_A wrong answers share "valid_nonfinal_spans_only"
// and syntax-valid but semantically wrong SQL. Concrete rollouts show:
//   - "SELECT id FROM high>>" (wrong table: "high" vs "highschooler"; no WHERE)
//   - "SELECT DISTINCT s1.country FROM singer>>" (alias, no INTERSECT)
//   - "SELECT a.address_id, ..." (alias, missing JOIN+GROUP BY+ORDER BY+LIMIT)
//
// Root cause: The previous Phase 3 (ConstrainedGeneration / RegenerateUnit)
// generates tokens until the SQL parser first accepts a complete parse state
// (e.g., "SELECT id FROM highschooler" is valid complete SQL), then Phase 4
// immediately closes the span there. The model never generates the full
// WHERE / JOIN / GROUP BY / ORDER BY / LIMIT needed for correctness.
//
// Fix: Replace Phase 3+4 with a single CloseSpanWithinBudget(400) call.
// CloseSpanWithinBudget tracks the LONGEST (most tokens) complete-parse prefix
// reached during generation, not the first. By giving the model 400 steps:
//   - It continues past "SELECT col FROM table" (a trivially complete parse)
//   - It can generate WHERE conditions, JOINs, aggregation, LIMIT
//   - The LAST/LONGEST complete state is what gets closed with ">>"
//   - Queries that naturally include full clauses benefit directly
//
// Phases:
// 1. ≤5 unconstrained steps for "SQL: <<" preamble
// 2. Force OpenConstrainedSpan if not already inside
// 3. CloseSpanWithinBudget(min(remaining, 400)) — generates AND closes at
//    the longest complete prefix, never stopping at first minimal completion
//
// Budget: 5 + 1 + 400 = 406 steps << 900 budget.
// Guidance: updated to explicitly ask for WHERE, JOIN, GROUP BY, LIMIT.
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 (parser_validity):
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
// Phase 1 preamble: Loop guard contains !insideConstrainedOut so the
//   implication is vacuous on every iteration. The only true-flip is via
//   RenderedEndsWith(generated,"<<"), setting currentConstrainedOut := [] which
//   satisfies IsValidPrefix([]) by the method precondition. EOS break leaves
//   insideConstrainedOut false (vacuously true).
//
// Phase 2 (OpenConstrainedSpan): Runs only when !insideConstrainedOut.
//   Postcondition sets insideOut := true, currentOut := []; IsValidPrefix([])
//   holds by the method precondition. No step that leaves insideConstrainedOut
//   true emits a non-[] currentConstrainedOut without a valid-prefix guarantee.
//
// Phase 3 (CloseSpanWithinBudget): Postcondition directly guarantees
//   `insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)`.
//   Either the span closes (insideConstrainedOut = false, implication vacuous)
//   or the span remains open with a parser-valid prefix by the helper contract.
//
// Invariant 2 (progress): |generated| <= |generatedPrefix| + steps
//
// Phase 1: UnconstrainedStep costs 1 step; appends 0 (EOS) or 1 (non-EOS)
//   token per iteration. Each iteration: steps += 1, |generated| += ≤ 1.
//   Invariant preserved step-by-step.
//
// Phase 2: OpenConstrainedSpan costs 1 step and appends exactly 1 "<<"
//   token. steps += 1, |generated| += 1. Ratio 1:1, invariant preserved.
//
// Phase 3: CloseSpanWithinBudget postcondition guarantees
//   |generatedOut| <= |generated_in| + closeBudget. We set steps += closeBudget.
//   closeBudget = min(remaining, 400) where remaining = maxSteps - old_steps, so
//   new_steps = old_steps + closeBudget <= old_steps + remaining = maxSteps. ✓
//   |generated_new| <= |generated_in| + closeBudget
//                   <= |generatedPrefix| + old_steps + closeBudget
//                   = |generatedPrefix| + new_steps. ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm, "Generate a complete SQL SELECT statement that fully answers the question. Always include WHERE conditions when filtering, JOINs when multiple tables are needed, GROUP BY for aggregation, ORDER BY and LIMIT when asked for ranked or single results. Use only the exact table and column names shown in the schema. Do not use table aliases. Format: SQL: <<sql_query>>");

var steps: nat := 0;

// Phase 1: Short preamble (at most 5 steps) to let model emit "SQL: <<" naturally
while steps < maxSteps && steps < 5 && !insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  var next := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  if next == eosToken {
    break;
  } else {
    generated := generated + [next];
    if RenderedEndsWith(generated, "<<") {
      insideConstrainedOut := true;
      currentConstrainedOut := [];
    }
  }
}

// Phase 2: Force open "<<" if not already inside constrained span
if !insideConstrainedOut && steps < maxSteps {
  var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
  generated := og;
  insideConstrainedOut := oi;
  currentConstrainedOut := oc;
  steps := steps + 1;
}

// Phase 3: Generate SQL content and close span at the LONGEST complete parse.
// CloseSpanWithinBudget tracks the most-token complete prefix reached during
// the 400-step window, allowing the model to generate full WHERE/JOIN/GROUP BY
// clauses rather than stopping at the first minimal complete SQL fragment.
if insideConstrainedOut && steps < maxSteps {
  var remaining := maxSteps - steps;
  var closeBudget: nat;
  if remaining <= 400 {
    closeBudget := remaining;
  } else {
    closeBudget := 400;
  }
  var cg, ci, cc := helpers.CloseSpanWithinBudget(
    lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
  );
  generated := cg;
  insideConstrainedOut := ci;
  currentConstrainedOut := cc;
  steps := steps + closeBudget;
}

cost := steps;

